"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { Archive, Building2, CheckCircle2, ChevronRight, ClipboardList, Download, ExternalLink, FileText, ImagePlus, KeyRound, LogOut, MapPin, Menu, Mic, PackageCheck, Pencil, Plus, RefreshCw, Search, Settings, Share2, Square, Trash2, Upload, UserRound, Users, X } from "lucide-react";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { authenticatedFetch, supabase } from "./supabase-client";

type Data = { me:any; territories:any[]; agents:any[]; clients:any[]; orders:any[]; items:any[]; files:any[] };
type View = "home"|"orders"|"pending"|"clients"|"archive"|"admin";
const empty: Data = { me:null, territories:[], agents:[], clients:[], orders:[], items:[], files:[] };
async function api(body:any){const r=await authenticatedFetch("/api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});if(!r.ok)throw new Error(await r.text());return r.json()}

export default function Dashboard({ signedInEmail, signedInName, onSignOut }: { signedInEmail:string; signedInName:string; onSignOut:()=>void }) {
  const [data,setData]=useState<Data>(empty), [view,setView]=useState<View>("home"), [orderScope,setOrderScope]=useState<"all"|"open"|"complete">("open"), [orderTerritory,setOrderTerritory]=useState("all"), [orderDateFrom,setOrderDateFrom]=useState(""), [orderDateTo,setOrderDateTo]=useState(""), [clientTerritory,setClientTerritory]=useState("all"), [documentGroup,setDocumentGroup]=useState("all"), [documentQuery,setDocumentQuery]=useState(""), [loading,setLoading]=useState(true), [error,setError]=useState(""), [query,setQuery]=useState(""), [menu,setMenu]=useState(false);
  const [modal,setModal]=useState<"client"|"order"|"agent"|"territory"|"upload"|null>(null), [selectedOrder,setSelectedOrder]=useState<any>(null), [editingClient,setEditingClient]=useState<any>(null), [editingDocument,setEditingDocument]=useState<any>(null), [sharedFileId,setSharedFileId]=useState<number|null>(null), [sharedPhoto,setSharedPhoto]=useState<File|null>(null), [installPrompt,setInstallPrompt]=useState<any>(null), [viewingFile,setViewingFile]=useState<any>(null);
  async function load(silent=false){ if(!silent)setLoading(true); setError(""); try { const r=await authenticatedFetch("/api/data"); if(!r.ok) throw new Error(await r.text()); setData(await r.json()); } catch(e:any){setError(e.message)} finally{if(!silent)setLoading(false)} }
  useEffect(()=>{load();const timer=setInterval(()=>load(true),15*60*1000);const refresh=()=>{if(document.visibilityState==="visible")load(true)};document.addEventListener("visibilitychange",refresh);if("serviceWorker" in navigator)navigator.serviceWorker.register("/sw.js",{updateViaCache:"none"}).then(reg=>reg.update()).catch(()=>{});const params=new URLSearchParams(window.location.search),shared=Number(params.get("sharedFile"));if(shared){setSharedFileId(shared);setModal("order");history.replaceState({},"",location.pathname)}if(params.get("sharedPhoto")){caches.match("/__shared-photo").then(async response=>{if(!response)throw new Error();const blob=await response.blob(),name=decodeURIComponent(response.headers.get("X-File-Name")||"foto-whatsapp.jpg");setSharedPhoto(new File([blob],name,{type:blob.type||"image/jpeg"}));setModal("order");history.replaceState({},"",location.pathname)}).catch(()=>alert("Non è stato possibile recuperare la foto condivisa."))}const shareError=params.get("shareError");if(shareError){alert(shareError==="size"?"Foto troppo grande (massimo 20 MB).":"La foto condivisa non è valida.");history.replaceState({},"",location.pathname)}const capture=(event:any)=>{event.preventDefault();setInstallPrompt(event)};window.addEventListener("beforeinstallprompt",capture);return()=>{clearInterval(timer);document.removeEventListener("visibilitychange",refresh);window.removeEventListener("beforeinstallprompt",capture)}},[]);
  async function install(){if(!installPrompt)return;await installPrompt.prompt();setInstallPrompt(null)}
  const isComplete=(order:any)=>!!order.completed_at;
  const pendingItems=data.items.filter(i=>Number(i.delivered_quantity||0)<Number(i.quantity)), pending=pendingItems.reduce((sum,item)=>sum+Math.max(0,Number(item.quantity)-Number(item.delivered_quantity||0)),0), openOrders=data.orders.filter(o=>!isComplete(o));
  const normalizedQuery=query.trim().toLocaleLowerCase("it");
  const filteredOrders=data.orders.filter(o=>{const itemText=data.items.filter(i=>i.order_id===o.id).map(i=>i.description).join(" ");const text=[o.client_name,o.territory_name,o.agent_name,o.notes,o.id,String(o.id).padStart(4,"0"),itemText].map(String).join(" ").toLocaleLowerCase("it");return !normalizedQuery||text.includes(normalizedQuery)});
  const orderMatchesDate=(order:any)=>{const date=new Date(order.created_at),key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;return (!orderDateFrom||key>=orderDateFrom)&&(!orderDateTo||key<=orderDateTo)};
  const normalizedDocumentQuery=documentQuery.trim().toLocaleLowerCase("it");
  const archiveFiles=data.files.filter(f=>f.category==="document"&&(documentGroup==="all"||(f.document_group||"Generale")===documentGroup)&&(!normalizedDocumentQuery||[f.title,f.filename,f.document_group].map(String).join(" ").toLocaleLowerCase("it").includes(normalizedDocumentQuery))).sort((a,b)=>String(a.title).localeCompare(String(b.title),"it",{sensitivity:"base",numeric:true}));
  const nav=[{id:"home",label:"Panoramica",icon:Building2},{id:"orders",label:"Ordini",icon:ClipboardList},{id:"clients",label:"Clienti",icon:Users},{id:"archive",label:"Archivio",icon:Archive},...(data.me?.role==="admin"?[{id:"admin",label:"Amministrazione",icon:Settings}]:[])] as any[];
  function go(v:View){if(v==="orders")setOrderScope("open");setView(v);setMenu(false)}
  function showOpenOrders(){setOrderScope("open");setView("orders")}
  if(error) return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><div className="max-w-lg rounded-3xl bg-white p-8 text-slate-900 shadow-2xl"><h1 className="text-2xl font-bold">Accesso non disponibile</h1><p className="mt-3 whitespace-pre-wrap text-sm text-slate-600">{error}</p><button className="mt-6 text-sm font-semibold text-orange-600" onClick={onSignOut}>Esci e usa un altro account</button></div></main>;
  return <div className="min-h-screen bg-[#f4f6f8] text-slate-900">
    <aside className={`fixed inset-y-0 left-0 z-40 w-72 bg-[#101d2c] p-5 text-white transition-transform lg:translate-x-0 ${menu?"translate-x-0":"-translate-x-full"}`}>
      <div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-xl bg-orange-500"><PackageCheck/></div><div><div className="font-bold tracking-tight">Ordini Agenti</div><div className="text-xs text-slate-400">Rete commerciale</div></div></div><button className="lg:hidden" onClick={()=>setMenu(false)}><X/></button></div>
      <nav className="mt-10 space-y-1">{nav.map(n=><button key={n.id} onClick={()=>go(n.id)} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left text-sm font-medium ${view===n.id?"bg-white/12 text-white":"text-slate-400 hover:bg-white/6 hover:text-white"}`}><n.icon className="size-5"/>{n.label}</button>)}</nav>
      <div className="absolute bottom-5 left-5 right-5 rounded-2xl bg-white/7 p-4"><div className="flex items-center gap-3"><ProfileAvatar user={data.me} className="size-10"/><div className="min-w-0"><div className="truncate text-sm font-semibold">{data.me?.name||signedInName}</div><div className="truncate text-xs text-slate-400">{data.me?.role==="admin"?"Amministratore":"Agente"}</div></div></div>{installPrompt&&<button onClick={install} className="mt-3 flex items-center gap-2 text-xs font-semibold text-orange-300"><Download className="size-4"/>Installa per condividere da WhatsApp</button>}<button onClick={onSignOut} className="mt-3 flex items-center gap-2 text-xs text-slate-400 hover:text-white"><LogOut className="size-4"/>Esci</button></div>
    </aside>
    <main className="lg:pl-72"><header className="sticky top-0 z-30 flex h-20 items-center gap-4 border-b bg-white/90 px-4 backdrop-blur sm:px-8"><button onClick={()=>setMenu(true)} className="lg:hidden"><Menu/></button><div className="relative max-w-xl flex-1"><Search className="absolute left-3 top-2.5 size-5 text-slate-400"/><Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Cerca cliente, ordine o articolo..." className="h-10 border-0 bg-slate-100 pl-10 shadow-none"/></div><div className="hidden text-right sm:block"><div className="text-sm font-semibold">{data.me?.name||signedInName}</div><div className="text-xs text-slate-500">{signedInEmail}</div></div></header>
      <div className="mx-auto max-w-7xl p-4 sm:p-8">{loading?<Loading/>:<>
        {view==="home"&&<><Title title={`Buon lavoro, ${(data.me?.name||signedInName).split(" ")[0]}`} subtitle="Ecco la situazione aggiornata della rete ordini." action={<Button onClick={()=>setModal("order")} className="bg-orange-500 hover:bg-orange-600"><Plus/>Nuovo ordine</Button>}/><div className="grid gap-4 sm:grid-cols-3"><Stat label="Ordini aperti" value={openOrders.length} icon={ClipboardList} tone="blue" onClick={showOpenOrders}/><Stat label="Pezzi ancora da consegnare" value={pending} icon={PackageCheck} tone="orange" onClick={()=>setView("pending")}/><Stat label="Archivio" value={data.files.filter(f=>f.category==="document").length} icon={Archive} tone="violet" onClick={()=>setView("archive")}/></div><ShareSetupCard installPrompt={installPrompt} install={install}/><FixingCard/><section className="mt-8"><div className="mb-4 flex items-center justify-between"><h2 className="text-xl font-bold">Ordini recenti da completare</h2><button onClick={()=>go("orders")} className="text-sm font-semibold text-orange-600">Vedi tutti</button></div><OrderList orders={filteredOrders.filter(o=>!isComplete(o)).slice(0,5)} data={data} onOpen={setSelectedOrder}/></section></>}
        {view==="orders"&&<><Title title="Ordini" subtitle="Gli ordini completati restano disponibili per 14 giorni, poi vengono eliminati automaticamente." action={<Button onClick={()=>setModal("order")} className="bg-orange-500 hover:bg-orange-600"><Plus/>Nuovo ordine</Button>}/><FilterBar><FilterSelect value={orderScope} onChange={setOrderScope as any} label="Stato" options={[["open","Da completare"],["complete","Completati"],["all","Tutti"]]}/><FilterSelect value={orderTerritory} onChange={setOrderTerritory} label="Territorio" options={[["all","Tutti i territori"],...data.territories.map(t=>[String(t.id),t.name])]}/><DateFilter label="Dal" value={orderDateFrom} onChange={setOrderDateFrom}/><DateFilter label="Al" value={orderDateTo} onChange={setOrderDateTo}/>{(orderDateFrom||orderDateTo)&&<Button variant="ghost" onClick={()=>{setOrderDateFrom("");setOrderDateTo("")}}>Azzera date</Button>}</FilterBar><GroupedOrderList orders={filteredOrders.filter(o=>(orderScope==="all"||(orderScope==="complete")===isComplete(o))&&(orderTerritory==="all"||String(o.territory_id)===orderTerritory)&&orderMatchesDate(o))} data={data} onOpen={setSelectedOrder} reload={load}/></>}
        {view==="pending"&&<><Title title="Articoli da consegnare" subtitle="Elenco operativo non raggruppato, utile per preparare gli acquisti ai fornitori."/><PendingItemList items={pendingItems} orders={data.orders} onOpen={setSelectedOrder}/></>}
        {view==="clients"&&<><Title title="Clienti" subtitle="Anagrafica organizzata per territorio e agente." action={<Button onClick={()=>setModal("client")} className="bg-orange-500 hover:bg-orange-600"><Plus/>Nuovo cliente</Button>}/><FilterBar><FilterSelect value={clientTerritory} onChange={setClientTerritory} label="Territorio" options={[["all","Tutti i territori"],...data.territories.map(t=>[String(t.id),t.name])]}/></FilterBar><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.clients.filter(c=>(clientTerritory==="all"||String(c.territory_id)===clientTerritory)&&(c.name+c.territory_name).toLowerCase().includes(query.toLowerCase())).map(c=><article key={c.id} className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><div className="grid size-11 place-items-center rounded-xl bg-slate-100"><Building2/></div><div className="flex items-center gap-2"><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700">{c.territory_name}</span><Button size="icon-sm" variant="ghost" aria-label={`Modifica ${c.name}`} onClick={()=>setEditingClient(c)}><Pencil className="size-4"/></Button></div></div><h3 className="mt-4 font-bold">{c.name}</h3><p className="mt-1 text-sm text-slate-500">{c.contact||"Nessun referente"} {c.phone&&`• ${c.phone}`}</p><p className="mt-3 flex gap-2 text-xs text-slate-500"><MapPin className="size-4"/>{c.address||"Indirizzo non inserito"}</p>{data.me.role==="admin"&&<p className="mt-3 text-xs font-medium text-slate-400">Agente: {c.agent_name}</p>}</article>)}</div></>}
        {view==="archive"&&<><Title title="Archivio tecnico" subtitle="Documenti consultabili e condivisibili direttamente dall’app." action={data.me.role==="admin"?<Button onClick={()=>setModal("upload")} className="bg-orange-500 hover:bg-orange-600"><Upload/>Carica documento</Button>:undefined}/><FilterBar><FilterSelect value={documentGroup} onChange={setDocumentGroup} label="Gruppo" options={[["all","Tutti i gruppi"],...Array.from(new Set(data.files.filter(f=>f.category==="document").map(f=>f.document_group||"Generale"))).sort().map(g=>[String(g),String(g)])]}/><div className="relative w-full sm:max-w-sm"><Search className="absolute left-3 top-2.5 size-5 text-slate-400"/><Input value={documentQuery} onChange={e=>setDocumentQuery(e.target.value)} placeholder="Cerca documento..." className="pl-10"/></div></FilterBar><div className="overflow-hidden rounded-2xl border bg-white">{archiveFiles.length?archiveFiles.map(f=><div key={f.id} className="flex items-center gap-2 border-b p-2 last:border-0 hover:bg-slate-50"><button onClick={()=>setViewingFile(f)} className="flex min-w-0 flex-1 items-center gap-4 p-2 text-left"><div className="grid size-11 shrink-0 place-items-center rounded-xl bg-red-50 text-red-600"><FileText/></div><div className="min-w-0 flex-1"><div className="truncate font-semibold">{f.title}</div><div className="truncate text-xs text-slate-500">{f.document_group||"Generale"} • {f.filename} • {new Date(f.created_at).toLocaleDateString("it-IT")}</div></div><ChevronRight className="text-slate-300"/></button><Button size="icon-sm" variant="ghost" title="Condividi" aria-label={`Condividi ${f.title}`} onClick={()=>shareStoredFile(f)}><Share2 className="size-4"/></Button>{data.me.role==="admin"&&<Button size="icon-sm" variant="ghost" aria-label={`Modifica ${f.title}`} onClick={()=>setEditingDocument(f)}><Pencil className="size-4"/></Button>}</div>):<Empty text="Nessun documento trovato"/>}</div></>}
        {view==="admin"&&<><Title title="Amministrazione" subtitle="Gestisci utenti, ruoli e gruppi territoriali."/><div className="grid gap-6 lg:grid-cols-2"><UserAdminCard users={data.agents} me={data.me} onAdd={()=>setModal("agent")} reload={load}/><TerritoryAdminCard territories={data.territories} clients={data.clients} onAdd={()=>setModal("territory")} reload={load}/></div></>}
      </>}</div>
    </main>
    <Forms modal={modal} setModal={setModal} data={data} reload={load} sharedFileId={sharedFileId} sharedPhoto={sharedPhoto} clearShared={()=>{setSharedFileId(null);setSharedPhoto(null);caches.keys().then(keys=>Promise.all(keys.map(key=>caches.open(key).then(cache=>cache.delete("/__shared-photo"))))).catch(()=>{})}}/><ClientEditor client={editingClient} close={()=>setEditingClient(null)} data={data} reload={load}/><DocumentEditor document={editingDocument} close={()=>setEditingDocument(null)} data={data} reload={load}/><OrderDetail order={selectedOrder} close={()=>setSelectedOrder(null)} data={data} reload={load}/><DocumentViewer file={viewingFile} close={()=>setViewingFile(null)}/>
  </div>
}

function Title({title,subtitle,action}:{title:string;subtitle:string;action?:React.ReactNode}){return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-2xl font-extrabold tracking-tight sm:text-3xl">{title}</h1><p className="mt-1 text-sm text-slate-500">{subtitle}</p></div>{action}</div>}
function FilterBar({children}:{children:React.ReactNode}){return <div className="mb-6 flex flex-col gap-3 rounded-2xl border bg-white p-4 sm:flex-row sm:flex-wrap">{children}</div>}
function FilterSelect({value,onChange,label,options}:{value:string;onChange:(v:any)=>void;label:string;options:any[][]}){return <Select value={value} onValueChange={onChange}><SelectTrigger className="w-full bg-white sm:w-64"><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{options.map(([id,name])=><SelectItem key={id} value={id}>{name}</SelectItem>)}</SelectContent></Select>}
function DateFilter({label,value,onChange}:{label:string;value:string;onChange:(value:string)=>void}){return <label className="flex min-w-40 items-center gap-2 rounded-md border bg-white px-3"><span className="text-sm font-semibold text-slate-500">{label}</span><Input type="date" value={value} onChange={event=>onChange(event.target.value)} className="border-0 px-0 shadow-none"/></label>}
async function shareStoredFile(file:any){try{const response=await authenticatedFetch(`/api/file/${file.id}`);if(!response.ok)throw new Error(await response.text());const blob=await response.blob(),shared=new File([blob],file.filename,{type:file.content_type||blob.type});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[shared]}))){await navigator.share({title:file.title,files:[shared]});return}const url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=file.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error:any){if(error?.name!=="AbortError")alert(error?.message||"Condivisione non riuscita")}}
function ProfileAvatar({user,className="size-11"}:{user:any;className?:string}){const [url,setUrl]=useState("");useEffect(()=>{let active=true,objectUrl="";if(user?.id&&user?.has_avatar)authenticatedFetch(`/api/avatar/${user.id}?v=${encodeURIComponent(user.avatar_updated_at||"")}`).then(async response=>{if(!response.ok)throw new Error();objectUrl=URL.createObjectURL(await response.blob());if(active)setUrl(objectUrl)}).catch(()=>{});else setUrl("");return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[user?.id,user?.has_avatar,user?.avatar_updated_at]);return <div className={`grid shrink-0 place-items-center overflow-hidden rounded-full bg-orange-500/20 text-orange-500 ${className}`}>{url?<img src={url} alt={user?.name?`Foto di ${user.name}`:"Foto profilo"} className="h-full w-full object-cover"/>:<UserRound className="size-1/2"/>}</div>}
function ShareSetupCard({installPrompt,install}:{installPrompt:any;install:()=>void}){const android=typeof navigator!=="undefined"&&/Android/i.test(navigator.userAgent),standalone=typeof window!=="undefined"&&window.matchMedia("(display-mode: standalone)").matches;if(!android)return null;return <section className="mt-6 rounded-2xl border border-blue-200 bg-blue-50 p-4"><div className="flex items-start gap-3"><ImagePlus className="mt-0.5 size-5 text-blue-700"/><div className="flex-1"><h2 className="font-bold text-blue-950">Condivisione foto da WhatsApp</h2><p className="mt-1 text-sm text-blue-800">{standalone?"L’app è installata. Se non compare in WhatsApp, rimuovila e reinstallala da Chrome per aggiornare la destinazione di condivisione.":"Per comparire nell’elenco Condividi di Android devi installare l’app da Chrome: un semplice collegamento sulla Home non basta."}</p>{installPrompt&&<Button onClick={install} className="mt-3 bg-blue-700 hover:bg-blue-800"><Download/>Installa app Android</Button>}</div></div></section>}
function FixingCard(){return <section className="mt-6 overflow-hidden rounded-2xl border bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b px-5 py-4"><div><h2 className="font-bold">Fixing metalli Legor</h2><p className="text-xs text-slate-500">Oro, argento e rodio · fonte ufficiale aggiornata in tempo reale</p></div><a href="https://legor.com/quotazioni/" target="_blank" rel="noreferrer" className="flex items-center gap-1 text-xs font-semibold text-orange-600">Apri su Legor <ExternalLink className="size-3"/></a></div><iframe title="Quotazioni metalli preziosi Legor" src="https://legor.com/quotazioni-iframe/" className="h-[330px] w-full border-0 bg-white"/><div className="flex items-center gap-2 border-t bg-slate-50 px-5 py-3 text-xs text-slate-500"><RefreshCw className="size-3"/>I dati sono mostrati direttamente da Legor e vanno confermati con i loro uffici commerciali.</div></section>}
function Stat({label,value,icon:Icon,tone,onClick}:{label:string;value:number;icon:any;tone:string;onClick?:()=>void}){const colors:any={blue:"bg-blue-50 text-blue-700",orange:"bg-orange-50 text-orange-700",green:"bg-emerald-50 text-emerald-700",violet:"bg-violet-50 text-violet-700"};const content=<><div className={`grid size-11 place-items-center rounded-xl ${colors[tone]}`}><Icon/></div><div className="mt-5 text-3xl font-extrabold">{value}</div><div className="mt-1 text-sm text-slate-500">{label}</div>{onClick&&<div className="mt-3 flex items-center gap-1 text-xs font-semibold text-orange-600">Apri <ChevronRight className="size-3"/></div>}</>;return onClick?<button onClick={onClick} className="rounded-2xl border bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-orange-200 hover:shadow-md">{content}</button>:<div className="rounded-2xl border bg-white p-5 shadow-sm">{content}</div>}
function OrderList({orders,data,onOpen,reload}:{orders:any[];data:Data;onOpen:(o:any)=>void;reload?:()=>void}){const [confirming,setConfirming]=useState<{order:any;action:"complete"|"delete"}|null>(null),[busy,setBusy]=useState(false);async function confirm(){if(!confirming)return;setBusy(true);try{await api({action:confirming.action==="complete"?"orderComplete":"orderDelete",orderId:confirming.order.id});setConfirming(null);await reload?.()}catch(error:any){alert(error.message)}finally{setBusy(false)}}return <><div className="space-y-3">{orders.length?orders.map(o=>{const items=data.items.filter(i=>i.order_id===o.id),requested=items.reduce((s,i)=>s+Number(i.quantity),0),done=items.reduce((s,i)=>s+Number(i.delivered_quantity||0),0),all=!!o.completed_at;return <article key={o.id} className="rounded-2xl border bg-white p-3 shadow-sm transition hover:border-orange-200"><div className="flex flex-col gap-3 sm:flex-row sm:items-center"><button onClick={()=>onOpen(o)} className="flex min-w-0 flex-1 items-center gap-4 rounded-xl p-1 text-left"><div className={`grid size-12 shrink-0 place-items-center rounded-xl ${all?"bg-emerald-50 text-emerald-600":"bg-orange-50 text-orange-600"}`}>{all?<CheckCircle2/>:<ClipboardList/>}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate font-bold">{o.client_name}</h3><span className="rounded-full bg-slate-100 px-2 py-0.5 text-[11px] font-semibold">#{String(o.id).padStart(4,"0")}</span>{all&&<span className="rounded-full bg-emerald-50 px-2 py-0.5 text-[11px] font-semibold text-emerald-700">Completato</span>}</div><div className="mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500"><span>{o.territory_name}</span><span className="font-semibold">Data ordine: {new Date(o.created_at).toLocaleDateString("it-IT")}</span>{data.me.role==="admin"&&<span>{o.agent_name}</span>}</div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className={`h-full ${all?"bg-emerald-500":"bg-orange-500"}`} style={{width:`${requested?done/requested*100:0}%`}}/></div></div><div className="text-right"><div className="text-sm font-bold">{done}/{requested}</div><div className="text-[11px] text-slate-400">pezzi</div></div><ChevronRight className="size-5 text-slate-300"/></button>{reload&&<div className="grid grid-cols-2 gap-2 sm:flex sm:flex-col">{!all&&<Button size="sm" variant="outline" disabled={busy} onClick={()=>setConfirming({order:o,action:"complete"})} className="text-emerald-700 hover:bg-emerald-50 hover:text-emerald-800"><CheckCircle2/>Completa</Button>}<Button size="sm" variant="outline" disabled={busy} onClick={()=>setConfirming({order:o,action:"delete"})} className="text-red-600 hover:bg-red-50 hover:text-red-700"><Trash2/>Elimina</Button></div>}</div></article>}):<Empty text="Nessun ordine trovato"/>}</div><AlertDialog open={!!confirming} onOpenChange={open=>!open&&!busy&&setConfirming(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{confirming?.action==="complete"?"Completare":"Eliminare"} l’ordine #{String(confirming?.order?.id||0).padStart(4,"0")}?</AlertDialogTitle><AlertDialogDescription>{confirming?.action==="complete"?"Tutti gli articoli verranno segnati come consegnati e l’ordine passerà tra i completati.":"L’ordine, gli articoli e tutti gli allegati verranno eliminati definitivamente."}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Annulla</AlertDialogCancel><AlertDialogAction disabled={busy} variant={confirming?.action==="delete"?"destructive":"default"} onClick={confirm}>{confirming?.action==="complete"?"Completa ordine":"Elimina ordine"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}
function GroupedOrderList({orders,data,onOpen,reload}:{orders:any[];data:Data;onOpen:(o:any)=>void;reload:()=>void}){const groups=Array.from(new Set(orders.map(o=>o.territory_name))).sort((a,b)=>String(a).localeCompare(String(b),"it"));return <div className="space-y-7">{groups.length?groups.map(territory=>{const list=orders.filter(o=>o.territory_name===territory);return <section key={String(territory)}><div className="mb-3 flex items-center gap-2"><MapPin className="size-5 text-orange-500"/><h2 className="text-lg font-extrabold">{territory}</h2><span className="rounded-full bg-slate-200 px-2 py-0.5 text-xs font-semibold">{list.length}</span></div><OrderList orders={list} data={data} onOpen={onOpen} reload={reload}/></section>}):<Empty text="Nessun ordine trovato"/>}</div>}
function PendingItemList({items,orders,onOpen}:{items:any[];orders:any[];onOpen:(o:any)=>void}){return <div className="space-y-2">{items.length?items.map(item=>{const order=orders.find(o=>o.id===item.order_id),remaining=Math.max(0,Number(item.quantity)-Number(item.delivered_quantity||0));return <button key={item.id} onClick={()=>order&&onOpen(order)} className="flex w-full items-center gap-4 rounded-2xl border bg-white p-4 text-left shadow-sm hover:border-orange-200"><div className="grid min-w-16 place-items-center rounded-xl bg-orange-50 px-3 py-2 text-orange-700"><div className="text-xl font-extrabold">{remaining}</div><div className="text-[10px] font-semibold uppercase">mancanti</div></div><div className="min-w-0 flex-1"><div className="font-bold">{item.description}</div><div className="mt-1 text-xs font-medium text-slate-600">Richiesti {item.quantity} · consegnati {item.delivered_quantity||0}</div><div className="mt-1 flex flex-wrap gap-2 text-xs text-slate-500"><span>{order?.client_name}</span><span>•</span><span>{order?.territory_name}</span><span>•</span><span>Ordine #{String(item.order_id).padStart(4,"0")}</span></div></div><ChevronRight className="size-5 text-slate-300"/></button>}):<Empty text="Nessun articolo da consegnare"/>}</div>}
function Empty({text}:{text:string}){return <div className="rounded-2xl border border-dashed bg-white p-12 text-center text-sm text-slate-400">{text}</div>}
function Loading(){return <div className="space-y-4">{[1,2,3].map(x=><div key={x} className="h-28 animate-pulse rounded-2xl bg-slate-200"/>)}</div>}
function UserAdminCard({users,me,onAdd,reload}:{users:any[];me:any;onAdd:()=>void;reload:()=>void}){
 const [editing,setEditing]=useState<any>(null),[deleting,setDeleting]=useState<any>(null),[busy,setBusy]=useState(false);
 async function request(body:any){setBusy(true);const r=await authenticatedFetch("/api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});setBusy(false);if(!r.ok){alert(await r.text());return false}await reload();return true}
 async function update(form:FormData){const body:any={action:"userUpdate",userId:editing.id};form.forEach((v,k)=>body[k]=v);if(editing.id===me.id){body.email=editing.email;body.role="admin"}if(await request(body))setEditing(null)}
 async function remove(){if(await request({action:"userDelete",userId:deleting.id}))setDeleting(null)}
 async function resetPassword(user:any){setBusy(true);const {error}=await supabase.auth.resetPasswordForEmail(user.email,{redirectTo:window.location.origin});setBusy(false);alert(error?error.message:`Email per reimpostare la password inviata a ${user.email}`)}
 async function uploadAvatar(target:any,file?:File){if(!file)return;setBusy(true);const form=new FormData();form.set("userId",String(target.id));form.set("file",file);const response=await authenticatedFetch("/api/avatar",{method:"POST",body:form});setBusy(false);if(!response.ok){alert(await response.text());return}await reload()}
 return <section className="rounded-2xl border bg-white p-5"><div className="flex items-center justify-between"><h2 className="text-lg font-bold">Utenti</h2><Button size="sm" variant="outline" onClick={onAdd}><Plus/>Aggiungi</Button></div><div className="mt-3 rounded-xl bg-blue-50 p-3 text-xs text-blue-800">Le password sono cifrate e non possono essere visualizzate. Puoi inviare all’utente un collegamento sicuro per sceglierne una nuova.</div><div className="mt-4 divide-y">{users.map(u=><div key={u.id} className="flex items-center gap-2 py-3"><label className="group relative cursor-pointer rounded-full" title={`Cambia foto di ${u.name}`}><ProfileAvatar user={u}/><span className="absolute inset-0 grid place-items-center rounded-full bg-slate-950/60 text-white opacity-0 transition group-hover:opacity-100"><ImagePlus className="size-4"/></span><input disabled={busy} className="sr-only" type="file" accept="image/*" onChange={event=>uploadAvatar(u,event.target.files?.[0])}/></label><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{u.name}{u.id===me.id&&<span className="ml-2 text-xs font-normal text-slate-400">(tu)</span>}</div><div className="truncate text-xs text-slate-500">{u.email}</div></div><span className="hidden rounded-full bg-slate-100 px-2 py-1 text-[11px] font-semibold sm:inline">{u.role==="admin"?"Amministratore":"Agente"}</span><Button size="icon-sm" variant="ghost" disabled={busy} title="Invia reimpostazione password" aria-label={`Reimposta password di ${u.name}`} onClick={()=>resetPassword(u)}><KeyRound className="size-4"/></Button><Button size="icon-sm" variant="ghost" aria-label={`Modifica ${u.name}`} onClick={()=>setEditing(u)}><Pencil className="size-4"/></Button><Button size="icon-sm" variant="ghost" disabled={u.id===me.id} aria-label={`Elimina ${u.name}`} onClick={()=>setDeleting(u)} className="text-red-600 hover:bg-red-50 hover:text-red-700"><Trash2 className="size-4"/></Button></div>)}</div>
 <Dialog open={!!editing} onOpenChange={o=>!o&&setEditing(null)}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Modifica utente</DialogTitle><DialogDescription>Aggiorna i dati e il livello di accesso.</DialogDescription></DialogHeader>{editing&&<form action={update} className="space-y-3"><Input name="name" required defaultValue={editing.name} placeholder="Nome e cognome"/><Input name="email" type="email" required defaultValue={editing.email} disabled={editing.id===me.id}/><Select name="role" defaultValue={editing.role} disabled={editing.id===me.id}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="agent">Agente</SelectItem><SelectItem value="admin">Amministratore</SelectItem></SelectContent></Select>{editing.id===me.id&&<p className="text-xs text-slate-500">Per sicurezza puoi modificare solo il tuo nome. Email e ruolo del tuo account restano bloccati.</p>}<Button disabled={busy} className="w-full bg-orange-500 hover:bg-orange-600">Salva modifiche</Button></form>}</DialogContent></Dialog>
 <AlertDialog open={!!deleting} onOpenChange={o=>!o&&setDeleting(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Eliminare {deleting?.name}?</AlertDialogTitle><AlertDialogDescription>L'utente perderà definitivamente l'accesso. L'eliminazione viene bloccata se risultano clienti, ordini o file collegati.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Annulla</AlertDialogCancel><AlertDialogAction disabled={busy} variant="destructive" onClick={remove}>Elimina utente</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 </section>
}

function TerritoryAdminCard({territories,clients,onAdd,reload}:{territories:any[];clients:any[];onAdd:()=>void;reload:()=>void}){
 const [editing,setEditing]=useState<any>(null),[deleting,setDeleting]=useState<any>(null),[busy,setBusy]=useState(false);
 async function request(body:any){setBusy(true);const r=await authenticatedFetch("/api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});setBusy(false);if(!r.ok){alert(await r.text());return false}await reload();return true}
 async function update(form:FormData){if(await request({action:"territoryUpdate",territoryId:editing.id,name:form.get("name")}))setEditing(null)}
 async function remove(){if(await request({action:"territoryDelete",territoryId:deleting.id}))setDeleting(null)}
 return <section className="rounded-2xl border bg-white p-5"><div className="flex items-center justify-between"><h2 className="text-lg font-bold">Zone</h2><Button size="sm" variant="outline" onClick={onAdd}><Plus/>Aggiungi</Button></div><div className="mt-4 divide-y">{territories.map(t=>{const total=clients.filter(c=>c.territory_id===t.id).length;return <div key={t.id} className="flex items-center gap-3 py-3"><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{t.name}</div><div className="text-xs text-slate-500">{total} {total===1?"cliente":"clienti"}</div></div><Button size="icon-sm" variant="ghost" aria-label={`Modifica ${t.name}`} onClick={()=>setEditing(t)}><Pencil className="size-4"/></Button><Button size="icon-sm" variant="ghost" aria-label={`Elimina ${t.name}`} onClick={()=>setDeleting(t)} className="text-red-600 hover:bg-red-50 hover:text-red-700"><Trash2 className="size-4"/></Button></div>})}</div>
 <Dialog open={!!editing} onOpenChange={o=>!o&&setEditing(null)}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Modifica zona</DialogTitle><DialogDescription>Aggiorna il nome della zona. I clienti collegati resteranno invariati.</DialogDescription></DialogHeader>{editing&&<form action={update} className="space-y-3"><Input name="name" required defaultValue={editing.name} placeholder="Nome zona"/><Button disabled={busy} className="w-full bg-orange-500 hover:bg-orange-600">Salva modifiche</Button></form>}</DialogContent></Dialog>
 <AlertDialog open={!!deleting} onOpenChange={o=>!o&&setDeleting(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Eliminare la zona {deleting?.name}?</AlertDialogTitle><AlertDialogDescription>La zona verrà eliminata definitivamente. Se contiene clienti, l'operazione sarà bloccata per evitare dati senza assegnazione.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Annulla</AlertDialogCancel><AlertDialogAction disabled={busy} variant="destructive" onClick={remove}>Elimina zona</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 </section>
}

function SearchableClientPicker({clients,selectedId,onSelect,query,setQuery,onCreate}:{clients:any[];selectedId:number|null;onSelect:(id:number|null)=>void;query:string;setQuery:(v:string)=>void;onCreate?:()=>void}){const selected=clients.find(c=>c.id===selectedId),matches=clients.filter(c=>(c.name+" "+c.territory_name).toLowerCase().includes(query.toLowerCase())).slice(0,8);return <div className="space-y-2"><label className="text-sm font-semibold">Cliente</label><div className="relative"><Search className="absolute left-3 top-2.5 size-5 text-slate-400"/><Input value={query} onChange={e=>{setQuery(e.target.value);onSelect(null)}} placeholder="Scrivi il nome del cliente..." className="pl-10"/></div>{selected&&<div className="flex items-center justify-between rounded-xl border border-orange-200 bg-orange-50 px-3 py-2 text-sm"><b>{selected.name}</b><span className="rounded-full bg-white px-2 py-1 text-xs font-semibold text-blue-700">{selected.territory_name}</span></div>}{query&&!selected&&<div className="max-h-56 overflow-y-auto rounded-xl border bg-white shadow-sm">{matches.map(c=><button type="button" key={c.id} onClick={()=>{onSelect(c.id);setQuery(c.name)}} className="flex w-full items-center justify-between border-b px-3 py-3 text-left last:border-0 hover:bg-slate-50"><span className="font-semibold">{c.name}</span><span className="rounded-full bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700">{c.territory_name}</span></button>)}{onCreate&&<button type="button" onClick={onCreate} className="flex w-full items-center gap-2 px-3 py-3 font-semibold text-orange-600 hover:bg-orange-50"><Plus className="size-4"/>Inserisci “{query}” come nuovo cliente</button>}</div>}</div>}

function ClientEditor({client,close,data,reload}:{client:any;close:()=>void;data:Data;reload:()=>void}){
 const [busy,setBusy]=useState(false),[deleting,setDeleting]=useState(false);if(!client)return null;
 async function save(form:FormData){setBusy(true);try{await api({action:"clientUpdate",clientId:client.id,name:form.get("name"),contact:form.get("contact"),phone:form.get("phone"),address:form.get("address"),territoryId:form.get("territoryId"),agentId:data.me.role==="admin"?form.get("agentId"):client.agent_id});await reload();close()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 async function remove(){setBusy(true);try{await api({action:"clientDelete",clientId:client.id});await reload();setDeleting(false);close()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 return <><Dialog open onOpenChange={o=>!o&&close()}><DialogContent className="sm:max-w-lg"><DialogHeader><DialogTitle>Modifica cliente</DialogTitle><DialogDescription>Aggiorna anagrafica, zona e assegnazione.</DialogDescription></DialogHeader><form action={save} className="space-y-3"><Input name="name" required defaultValue={client.name}/><div className="grid gap-3 sm:grid-cols-2"><Input name="contact" defaultValue={client.contact} placeholder="Referente"/><Input name="phone" defaultValue={client.phone} placeholder="Telefono"/></div><Input name="address" defaultValue={client.address} placeholder="Indirizzo"/><SelectField name="territoryId" label="Territorio" items={data.territories} defaultValue={String(client.territory_id)}/>{data.me.role==="admin"&&<SelectField name="agentId" label="Responsabile cliente" items={data.agents.filter(a=>a.active)} defaultValue={String(client.agent_id)}/>}<div className="flex gap-2"><Button type="button" variant="outline" onClick={()=>setDeleting(true)} className="text-red-600"><Trash2/>Elimina</Button><Button disabled={busy} className="flex-1 bg-orange-500">Salva modifiche</Button></div></form></DialogContent></Dialog><AlertDialog open={deleting} onOpenChange={setDeleting}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Eliminare {client.name}?</AlertDialogTitle><AlertDialogDescription>Il cliente verrà eliminato definitivamente. Se ha ordini collegati, l’operazione sarà bloccata per proteggere lo storico.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Annulla</AlertDialogCancel><AlertDialogAction variant="destructive" disabled={busy} onClick={remove}>Elimina cliente</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}

function Forms({modal,setModal,data,reload,sharedFileId,sharedPhoto,clearShared}:{modal:any;setModal:(x:any)=>void;data:Data;reload:()=>void;sharedFileId:number|null;sharedPhoto:File|null;clearShared:()=>void}){
 const [busy,setBusy]=useState(false),[rows,setRows]=useState([{description:"",quantity:1}]),[clientQuery,setClientQuery]=useState(""),[clientId,setClientId]=useState<number|null>(null),[orderTerritoryId,setOrderTerritoryId]=useState(""),[orderAgentId,setOrderAgentId]=useState(""),[quick,setQuick]=useState(false),[files,setFiles]=useState<File[]>([]),[recording,setRecording]=useState(false),[seconds,setSeconds]=useState(0),[audioUrl,setAudioUrl]=useState(""),[quickData,setQuickData]=useState({name:"",contact:"",phone:"",address:"",territoryId:"",agentId:""});
 const recorderRef=useRef<MediaRecorder|null>(null),streamRef=useRef<MediaStream|null>(null),chunksRef=useRef<Blob[]>([]),timerRef=useRef<ReturnType<typeof setInterval>|null>(null);
 useEffect(()=>()=>{if(timerRef.current)clearInterval(timerRef.current);streamRef.current?.getTracks().forEach(track=>track.stop());if(audioUrl)URL.revokeObjectURL(audioUrl)},[audioUrl]);
 useEffect(()=>{if(modal==="order"&&data.me?.id&&!orderAgentId)setOrderAgentId(String(data.me.id))},[modal,data.me?.id,orderAgentId]);
 useEffect(()=>{if(modal==="order"&&sharedPhoto)setFiles(current=>current.includes(sharedPhoto)?current:[...current,sharedPhoto])},[modal,sharedPhoto]);
 async function startRecording(){try{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==="undefined")throw new Error("Il browser non supporta la registrazione diretta");const stream=await navigator.mediaDevices.getUserMedia({audio:true});streamRef.current=stream;chunksRef.current=[];const mime=MediaRecorder.isTypeSupported("audio/webm;codecs=opus")?"audio/webm;codecs=opus":"";const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);recorderRef.current=recorder;recorder.ondataavailable=e=>{if(e.data.size)chunksRef.current.push(e.data)};recorder.onstop=()=>{const type=recorder.mimeType||"audio/webm",blob=new Blob(chunksRef.current,{type}),file=new File([blob],`nota-vocale-${new Date().toISOString().replace(/[:.]/g,"-")}.webm`,{type});setFiles(current=>[...current,file]);setAudioUrl(current=>{if(current)URL.revokeObjectURL(current);return URL.createObjectURL(blob)});stream.getTracks().forEach(track=>track.stop())};recorder.start(250);setSeconds(0);setRecording(true);timerRef.current=setInterval(()=>setSeconds(value=>value+1),1000)}catch(e:any){alert(`Microfono non disponibile: ${e.message}`)}}
 function stopRecording(){if(recorderRef.current?.state==="recording")recorderRef.current.stop();if(timerRef.current)clearInterval(timerRef.current);timerRef.current=null;setRecording(false)}
 async function json(action:string,form:FormData){setBusy(true);try{const body:any={action};form.forEach((v,k)=>body[k]=v);await api(body);setModal(null);await reload()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 async function upload(form:FormData){setBusy(true);form.set("category","document");const r=await authenticatedFetch("/api/upload",{method:"POST",body:form});setBusy(false);if(!r.ok){alert(await r.text());return}setModal(null);reload()}
 async function quickClient(){setBusy(true);try{const result=await api({action:"client",...quickData,name:quickData.name||clientQuery,agentId:data.me.role==="admin"?(quickData.agentId||data.me.id):data.me.id});setClientId(result.clientId);setClientQuery(quickData.name||clientQuery);setQuick(false);await reload()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 async function createOrder(form:FormData){if(!orderTerritoryId){alert("Seleziona il territorio");return}if(!clientId){alert("Seleziona o crea un cliente");return}if(!orderAgentId){alert("Seleziona l’agente");return}if(recording){alert("Ferma prima la registrazione");return}if(!rows.some(row=>row.description.trim())&&!files.length&&!sharedFileId){alert("Inserisci almeno un articolo oppure registra una nota vocale");return}setBusy(true);try{const result=await api({action:"order",clientId,agentId:Number(orderAgentId),notes:form.get("notes"),items:rows,sharedFileId});for(const file of files){const payload=new FormData();payload.set("category","order");payload.set("orderId",String(result.orderId));payload.set("title",file.name);payload.set("file",file);const r=await authenticatedFetch("/api/upload",{method:"POST",body:payload});if(!r.ok)throw new Error(await r.text())}setModal(null);setRows([{description:"",quantity:1}]);setClientId(null);setClientQuery("");setOrderTerritoryId("");setOrderAgentId(String(data.me.id));setFiles([]);if(audioUrl)URL.revokeObjectURL(audioUrl);setAudioUrl("");setSeconds(0);clearShared();await reload()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 function closeModal(){if(recording)stopRecording();setModal(null)}
 return <Dialog open={!!modal} onOpenChange={o=>!o&&closeModal()}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-xl"><DialogHeader><DialogTitle>{modal==="client"?"Nuovo cliente":modal==="order"?"Nuovo ordine":modal==="agent"?"Nuovo utente":modal==="territory"?"Nuovo territorio":"Carica documento"}</DialogTitle><DialogDescription>Compila i dati richiesti e salva.</DialogDescription></DialogHeader>
 {modal==="client"&&<form action={f=>json("client",f)} className="space-y-3"><Input name="name" required placeholder="Ragione sociale *"/><div className="grid gap-3 sm:grid-cols-2"><Input name="contact" placeholder="Referente"/><Input name="phone" placeholder="Telefono"/></div><Input name="address" placeholder="Indirizzo"/><SelectField name="territoryId" label="Territorio" items={data.territories}/>{data.me.role==="admin"&&<SelectField name="agentId" label="Responsabile cliente" items={data.agents.filter(a=>a.active)} defaultValue={String(data.me.id)}/>}<Button disabled={busy} className="w-full bg-orange-500">Salva cliente</Button></form>}
 {modal==="order"&&<form action={createOrder} className="space-y-3">
  <div className="grid gap-3 sm:grid-cols-2"><Select value={orderTerritoryId} onValueChange={v=>{setOrderTerritoryId(v);setClientId(null);setClientQuery("");setQuickData({...quickData,territoryId:v})}}><SelectTrigger className="w-full"><SelectValue placeholder="Territorio *"/></SelectTrigger><SelectContent>{data.territories.map(t=><SelectItem key={t.id} value={String(t.id)}>{t.name}</SelectItem>)}</SelectContent></Select><Select value={orderAgentId} onValueChange={setOrderAgentId}><SelectTrigger className="w-full"><SelectValue placeholder="Agente *"/></SelectTrigger><SelectContent>{data.agents.filter(a=>a.active).map(a=><SelectItem key={a.id} value={String(a.id)}>{a.name}{a.id===data.me.id?" (tu)":""}</SelectItem>)}</SelectContent></Select></div>
  <SearchableClientPicker clients={data.clients.filter(c=>!orderTerritoryId||String(c.territory_id)===orderTerritoryId)} selectedId={clientId} onSelect={setClientId} query={clientQuery} setQuery={setClientQuery} onCreate={()=>{setQuick(true);setQuickData({...quickData,name:clientQuery,territoryId:orderTerritoryId,agentId:orderAgentId})}}/>
  {quick&&<div className="space-y-2 rounded-xl border border-orange-200 bg-orange-50 p-3"><div className="flex items-center justify-between text-sm font-bold">Nuovo cliente<Button type="button" size="icon-sm" variant="ghost" onClick={()=>setQuick(false)}><X/></Button></div><Input value={quickData.name} onChange={e=>setQuickData({...quickData,name:e.target.value})} placeholder="Ragione sociale *"/><div className="grid gap-2 sm:grid-cols-2"><Input value={quickData.contact} onChange={e=>setQuickData({...quickData,contact:e.target.value})} placeholder="Referente"/><Input value={quickData.phone} onChange={e=>setQuickData({...quickData,phone:e.target.value})} placeholder="Telefono"/></div><Input value={quickData.address} onChange={e=>setQuickData({...quickData,address:e.target.value})} placeholder="Indirizzo"/><Select value={quickData.territoryId} onValueChange={v=>setQuickData({...quickData,territoryId:v})}><SelectTrigger className="w-full bg-white"><SelectValue placeholder="Territorio"/></SelectTrigger><SelectContent>{data.territories.map(t=><SelectItem key={t.id} value={String(t.id)}>{t.name}</SelectItem>)}</SelectContent></Select>{data.me.role==="admin"&&<Select value={quickData.agentId} onValueChange={v=>setQuickData({...quickData,agentId:v})}><SelectTrigger className="w-full bg-white"><SelectValue placeholder="Responsabile cliente"/></SelectTrigger><SelectContent>{data.agents.filter(a=>a.active).map(a=><SelectItem key={a.id} value={String(a.id)}>{a.name}</SelectItem>)}</SelectContent></Select>}<Button type="button" disabled={busy||!quickData.name||!quickData.territoryId} onClick={quickClient} className="w-full">Crea e seleziona</Button></div>}
  <textarea name="notes" className="min-h-20 w-full rounded-md border p-3 text-sm" placeholder="Note generali"/>
  <div><div className="text-sm font-bold">Articoli <span className="font-normal text-slate-400">(facoltativi con nota vocale)</span></div>{rows.map((r,i)=><div key={i} className="mt-2 flex gap-2"><Input value={r.description} onChange={e=>setRows(rows.map((x,n)=>n===i?{...x,description:e.target.value}:x))} placeholder="Descrizione articolo"/><Input className="w-20" type="number" min="1" value={r.quantity} onChange={e=>setRows(rows.map((x,n)=>n===i?{...x,quantity:Number(e.target.value)}:x))}/>{rows.length>1&&<Button type="button" variant="ghost" onClick={()=>setRows(rows.filter((_,n)=>n!==i))}><X/></Button>}</div>)}</div>
  <Button type="button" variant="outline" onClick={()=>setRows([...rows,{description:"",quantity:1}])}><Plus/>Aggiungi riga</Button>
  <div className="rounded-xl border border-dashed p-3"><div className="mb-2 flex items-center gap-2 text-sm font-bold"><ImagePlus className="size-4 text-orange-500"/>Foto e note vocali</div>{(sharedFileId||sharedPhoto)&&<p className="mb-2 rounded-lg bg-emerald-50 p-2 text-xs font-semibold text-emerald-700">Foto WhatsApp già allegata</p>}<div className="mb-3 rounded-xl bg-slate-50 p-3">{recording?<Button type="button" variant="destructive" onClick={stopRecording} className="w-full"><Square className="fill-current"/>Ferma registrazione · {Math.floor(seconds/60)}:{String(seconds%60).padStart(2,"0")}</Button>:<Button type="button" variant="outline" onClick={startRecording} className="w-full border-orange-200 text-orange-700"><Mic/>Registra nota vocale ora</Button>}{audioUrl&&<audio controls src={audioUrl} className="mt-3 w-full"/>}</div><Input type="file" accept="image/*,audio/*" multiple onChange={e=>setFiles(current=>[...current,...Array.from(e.target.files??[])])}/>{files.length>0&&<p className="mt-2 text-xs font-semibold text-emerald-700">{files.length} allegati pronti</p>}<p className="mt-2 text-xs text-slate-500">Puoi creare l’ordine usando soltanto la nota vocale o una foto e completarlo successivamente.</p></div>
  <Button disabled={busy||recording} className="w-full bg-orange-500">Crea ordine</Button>
 </form>}
 {modal==="agent"&&<form action={f=>json("agent",f)} className="space-y-3"><Input name="name" required placeholder="Nome e cognome"/><Input name="email" type="email" required placeholder="Email di accesso"/><Select name="role" defaultValue="agent" required><SelectTrigger className="w-full"><SelectValue placeholder="Ruolo"/></SelectTrigger><SelectContent><SelectItem value="agent">Agente</SelectItem><SelectItem value="admin">Amministratore</SelectItem></SelectContent></Select><p className="text-xs text-slate-500">L’utente dovrà registrarsi usando esattamente questa email. Gli agenti vedono solo i propri dati; gli amministratori possono gestire l’intera rete.</p><Button disabled={busy} className="w-full bg-orange-500">Crea utente</Button></form>}
 {modal==="territory"&&<form action={f=>json("territory",f)} className="space-y-3"><Input name="name" required placeholder="Nome territorio"/><Button disabled={busy} className="w-full bg-orange-500">Crea territorio</Button></form>}
 {modal==="upload"&&<form action={upload} className="space-y-3"><Input name="title" required placeholder="Titolo documento"/><Input name="documentGroup" required list="document-groups" placeholder="Gruppo documenti (es. Schede tecniche leghe)"/><datalist id="document-groups">{Array.from(new Set(data.files.filter(f=>f.category==="document").map(f=>f.document_group||"Generale"))).map(group=><option key={String(group)} value={String(group)}/>)}</datalist><Input name="file" required type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*"/><p className="text-xs text-slate-500">Puoi scegliere un gruppo esistente o scriverne uno nuovo. Dimensione massima 20 MB.</p><Button disabled={busy} className="w-full bg-orange-500">Carica</Button></form>}
 </DialogContent></Dialog>
}
function SelectField({name,label,items,defaultValue}:{name:string;label:string;items:any[];defaultValue?:string}){return <Select name={name} required defaultValue={defaultValue}><SelectTrigger className="w-full"><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{items.map(x=><SelectItem key={x.id} value={String(x.id)}>{x.name}</SelectItem>)}</SelectContent></Select>}

function SecureAttachment({file}:{file:any}){const [url,setUrl]=useState("");useEffect(()=>{let active=true,objectUrl="";if(file.content_type?.startsWith("audio/"))authenticatedFetch(`/api/file/${file.id}`).then(async response=>{if(!response.ok)throw new Error(await response.text());objectUrl=URL.createObjectURL(await response.blob());if(active)setUrl(objectUrl)}).catch(()=>{});return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[file.id,file.content_type]);async function open(){const response=await authenticatedFetch(`/api/file/${file.id}`);if(!response.ok){alert(await response.text());return}const objectUrl=URL.createObjectURL(await response.blob());window.open(objectUrl,"_blank","noopener,noreferrer");setTimeout(()=>URL.revokeObjectURL(objectUrl),60000)}return file.content_type?.startsWith("audio/")?<div className="rounded-xl border bg-slate-50 p-3"><div className="mb-2 flex items-center gap-2 text-xs font-semibold"><Mic className="size-4 text-orange-500"/>{file.title}</div>{url?<audio controls preload="metadata" src={url} className="w-full"/>:<p className="text-xs text-slate-400">Caricamento nota vocale…</p>}</div>:<button type="button" onClick={open} className="block w-full rounded-lg bg-slate-100 px-3 py-2 text-left text-xs font-semibold hover:bg-slate-200">{file.title}</button>}
function AttachmentList({attachments}:{attachments:any[]}){return attachments.length?<div><h3 className="mb-2 text-sm font-bold">Allegati</h3><div className="space-y-2">{attachments.map(file=><SecureAttachment key={file.id} file={file}/>)}</div></div>:null}
function DocumentEditor({document:doc,close,data,reload}:{document:any;close:()=>void;data:Data;reload:()=>void}){const [busy,setBusy]=useState(false),[deleting,setDeleting]=useState(false);if(!doc)return null;async function save(form:FormData){setBusy(true);try{const replacement=form.get("file");if(replacement instanceof File&&replacement.size>0){form.set("category","document");form.set("documentId",String(doc.id));const response=await authenticatedFetch("/api/upload",{method:"POST",body:form});if(!response.ok)throw new Error(await response.text())}else await api({action:"documentUpdate",documentId:doc.id,title:form.get("title"),documentGroup:form.get("documentGroup")});await reload();close()}catch(e:any){alert(e.message)}finally{setBusy(false)}}async function remove(){setBusy(true);try{await api({action:"documentDelete",documentId:doc.id});await reload();setDeleting(false);close()}catch(e:any){alert(e.message)}finally{setBusy(false)}}return <><Dialog open onOpenChange={o=>!o&&close()}><DialogContent><DialogHeader><DialogTitle>Modifica documento</DialogTitle><DialogDescription>Aggiorna titolo, gruppo o sostituisci il file.</DialogDescription></DialogHeader><form action={save} className="space-y-3"><Input name="title" required defaultValue={doc.title} placeholder="Titolo documento"/><Input name="documentGroup" required list="edit-document-groups" defaultValue={doc.document_group||"Generale"} placeholder="Gruppo"/><datalist id="edit-document-groups">{Array.from(new Set(data.files.filter(f=>f.category==="document").map(f=>f.document_group||"Generale"))).map(group=><option key={String(group)} value={String(group)}/>)}</datalist><div><label className="mb-1.5 block text-sm font-semibold">Sostituisci il file <span className="font-normal text-slate-400">(facoltativo)</span></label><Input name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*"/></div><div className="flex gap-2"><Button type="button" variant="outline" onClick={()=>setDeleting(true)} className="text-red-600"><Trash2/>Elimina</Button><Button disabled={busy} className="flex-1 bg-orange-500">Salva modifiche</Button></div></form></DialogContent></Dialog><AlertDialog open={deleting} onOpenChange={setDeleting}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Eliminare “{doc.title}”?</AlertDialogTitle><AlertDialogDescription>Il documento e il relativo file verranno eliminati definitivamente dall’archivio.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Annulla</AlertDialogCancel><AlertDialogAction variant="destructive" disabled={busy} onClick={remove}>Elimina documento</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}
function PdfPage({pdf,pageNumber}:{pdf:any;pageNumber:number}){const canvasRef=useRef<HTMLCanvasElement|null>(null);useEffect(()=>{let cancelled=false,renderTask:any;(async()=>{const page=await pdf.getPage(pageNumber);if(cancelled||!canvasRef.current)return;const viewport=page.getViewport({scale:1.5}),canvas=canvasRef.current,context=canvas.getContext("2d");if(!context)return;canvas.width=viewport.width;canvas.height=viewport.height;renderTask=page.render({canvasContext:context,viewport});await renderTask.promise})().catch(()=>{});return()=>{cancelled=true;renderTask?.cancel()}},[pdf,pageNumber]);return <canvas ref={canvasRef} aria-label={`Pagina ${pageNumber}`} className="mx-auto h-auto max-w-full rounded bg-white shadow"/>}
function PdfPreview({data,title}:{data:Uint8Array;title:string}){const [pdf,setPdf]=useState<any>(null),[error,setError]=useState("");useEffect(()=>{let active=true,task:any;(async()=>{const [pdfjs,worker]=await Promise.all([import("pdfjs-dist/legacy/build/pdf.mjs"),import("pdfjs-dist/legacy/build/pdf.worker.min.mjs?url")]);pdfjs.GlobalWorkerOptions.workerSrc=worker.default;task=pdfjs.getDocument({data:data.slice()});const document=await task.promise;if(active)setPdf(document)})().catch(e=>active&&setError(e instanceof Error?e.message:"PDF non leggibile"));return()=>{active=false;task?.destroy()}},[data]);if(error)return <div className="grid h-full place-items-center p-6 text-center text-sm text-red-600">Impossibile visualizzare il PDF: {error}</div>;if(!pdf)return <div className="grid h-full place-items-center text-sm text-slate-500">Preparazione del PDF…</div>;return <div role="document" aria-label={title} className="h-full space-y-3 overflow-auto p-2">{Array.from({length:pdf.numPages},(_,index)=><PdfPage key={index+1} pdf={pdf} pageNumber={index+1}/>)}</div>}
function DocumentViewer({file,close}:{file:any;close:()=>void}){const [url,setUrl]=useState(""),[pdfData,setPdfData]=useState<Uint8Array|null>(null),[error,setError]=useState("");useEffect(()=>{let active=true,objectUrl="";if(file)authenticatedFetch(`/api/file/${file.id}`).then(async r=>{if(!r.ok)throw new Error(await r.text());const blob=await r.blob();objectUrl=URL.createObjectURL(blob);const data=file.content_type==="application/pdf"?new Uint8Array(await blob.arrayBuffer()):null;if(active){setUrl(objectUrl);setPdfData(data)}}).catch(e=>active&&setError(e.message));return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl);setUrl("");setPdfData(null);setError("")}},[file]);if(!file)return null;const isPdf=file.content_type==="application/pdf",previewable=isPdf||file.content_type?.startsWith("image/"),ready=isPdf?!!pdfData:!!url;return <Dialog open onOpenChange={o=>!o&&close()}><DialogContent className="flex h-[92vh] max-w-5xl flex-col overflow-hidden p-0"><DialogHeader className="border-b p-4 pr-12"><DialogTitle>{file.title}</DialogTitle><DialogDescription>{file.document_group||"Generale"} · {file.filename}</DialogDescription></DialogHeader><div className="min-h-0 flex-1 bg-slate-200 p-2">{error?<div className="grid h-full place-items-center text-sm text-red-600">{error}</div>:!ready?<div className="grid h-full place-items-center text-sm text-slate-500">Caricamento documento…</div>:previewable?isPdf?<PdfPreview data={pdfData!} title={file.title}/>:<img src={url} alt={file.title} className="mx-auto h-full max-h-[75vh] object-contain"/>:<div className="grid h-full place-items-center"><a href={url} download={file.filename} className="rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white">Scarica per aprire questo formato</a></div>}</div>{url&&<div className="flex justify-end border-t bg-white p-3"><a href={url} download={file.filename} className="flex items-center gap-2 text-sm font-semibold text-orange-600"><Download className="size-4"/>Scarica una copia</a></div>}</DialogContent></Dialog>}

function OrderDetail({order,close,data,reload}:{order:any;close:()=>void;data:Data;reload:()=>void}){
 const [busy,setBusy]=useState(false),[editing,setEditing]=useState(false),[deleting,setDeleting]=useState(false),[clientId,setClientId]=useState<number|null>(null),[agentId,setAgentId]=useState(""),[clientQuery,setClientQuery]=useState(""),[notes,setNotes]=useState(""),[editRows,setEditRows]=useState<any[]>([]);
 useEffect(()=>{if(order){setClientId(order.client_id);setAgentId(String(order.agent_id));setClientQuery(order.client_name);setNotes(order.notes||"");setEditRows(data.items.filter(i=>i.order_id===order.id).map(i=>({description:i.description,quantity:i.quantity,deliveredQuantity:Number(i.delivered_quantity||0),delivered:Number(i.delivered_quantity||0)>=Number(i.quantity)})));setEditing(false)}},[order,data.items]);
 if(!order)return null;const items=data.items.filter(i=>i.order_id===order.id),attachments=data.files.filter(f=>f.category==="order"&&f.order_id===order.id);
 async function delivery(item:any,deliveredQuantity:number,complete=false){setBusy(true);try{await api({action:"delivery",itemId:item.id,deliveredQuantity,complete});await reload()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 async function upload(f:FormData){setBusy(true);f.set("category","order");f.set("orderId",String(order.id));const r=await authenticatedFetch("/api/upload",{method:"POST",body:f});setBusy(false);if(!r.ok)alert(await r.text());else reload()}
 async function save(){if(!clientId)return;setBusy(true);try{await api({action:"orderUpdate",orderId:order.id,clientId,agentId:Number(agentId),notes,items:editRows});await reload();close()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 async function remove(){setBusy(true);try{await api({action:"orderDelete",orderId:order.id});await reload();setDeleting(false);close()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 return <><Dialog open onOpenChange={o=>!o&&close()}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>{order.client_name} <span className="text-slate-400">#{String(order.id).padStart(4,"0")}</span></DialogTitle><DialogDescription>{order.territory_name} • {new Date(order.created_at).toLocaleDateString("it-IT")}</DialogDescription></DialogHeader>
 {editing?<div className="space-y-3"><AttachmentList attachments={attachments}/><SearchableClientPicker clients={data.clients} selectedId={clientId} onSelect={setClientId} query={clientQuery} setQuery={setClientQuery}/><Select value={agentId} onValueChange={setAgentId}><SelectTrigger className="w-full"><SelectValue placeholder="Agente"/></SelectTrigger><SelectContent>{data.agents.filter(a=>a.active).map(a=><SelectItem key={a.id} value={String(a.id)}>{a.name}</SelectItem>)}</SelectContent></Select><textarea value={notes} onChange={e=>setNotes(e.target.value)} className="min-h-20 w-full rounded-md border p-3 text-sm" placeholder="Note generali"/><div className="text-sm font-bold">Articoli e quantità</div>{editRows.map((r,i)=><div key={i} className="grid grid-cols-[auto_1fr_76px_76px_auto] items-center gap-2"><Checkbox checked={!!r.delivered} onCheckedChange={v=>setEditRows(editRows.map((x,n)=>n===i?{...x,delivered:!!v,deliveredQuantity:v?x.quantity:0}:x))}/><Input value={r.description} onChange={e=>setEditRows(editRows.map((x,n)=>n===i?{...x,description:e.target.value}:x))}/><Input aria-label="Quantità richiesta" title="Richiesta" type="number" min="1" value={r.quantity} onChange={e=>setEditRows(editRows.map((x,n)=>n===i?{...x,quantity:Number(e.target.value),deliveredQuantity:Math.min(Number(e.target.value),x.deliveredQuantity)}:x))}/><Input aria-label="Quantità consegnata" title="Consegnata" type="number" min="0" max={r.quantity} value={r.deliveredQuantity} onChange={e=>setEditRows(editRows.map((x,n)=>n===i?{...x,deliveredQuantity:Math.min(x.quantity,Math.max(0,Number(e.target.value))),delivered:Number(e.target.value)>=x.quantity}:x))}/><Button type="button" size="icon-sm" variant="ghost" onClick={()=>setEditRows(editRows.filter((_,n)=>n!==i))}><X/></Button></div>)}<div className="grid grid-cols-2 gap-2 px-10 text-[11px] text-slate-500"><span>Quantità richiesta</span><span className="text-right">Quantità consegnata</span></div><Button type="button" variant="outline" onClick={()=>setEditRows([...editRows,{description:"",quantity:1,deliveredQuantity:0,delivered:false}])}><Plus/>Aggiungi riga</Button><div className="flex gap-2"><Button variant="outline" onClick={()=>setEditing(false)} className="flex-1">Annulla</Button><Button disabled={busy||!editRows.length} onClick={save} className="flex-1 bg-orange-500">Salva modifiche</Button></div></div>:<div className="space-y-3"><div className="flex gap-2"><Button variant="outline" onClick={()=>setEditing(true)}><Pencil/>Modifica e trascrivi</Button><Button variant="outline" onClick={()=>setDeleting(true)} className="text-red-600"><Trash2/>Elimina</Button></div>{items.length?<div className="space-y-2">{items.map(i=>{const delivered=Number(i.delivered_quantity||0),remaining=Math.max(0,Number(i.quantity)-delivered),complete=delivered>=Number(i.quantity);return <div key={i.id} className={`flex items-center gap-3 rounded-xl border p-3 ${complete?"bg-emerald-50/60":"bg-white"}`}><Checkbox disabled={busy} checked={complete} onCheckedChange={v=>delivery(i,0,!!v)} className="size-5"/><div className="min-w-0 flex-1"><div className={`text-sm font-semibold ${complete?"text-slate-400 line-through":""}`}>{i.description}</div><div className="mt-1 flex flex-wrap gap-2 text-xs text-slate-500"><span>Richiesti: <b>{i.quantity}</b></span><span>Consegnati:</span><Input aria-label={`Quantità consegnata per ${i.description}`} className="h-7 w-20" type="number" min="0" max={i.quantity} defaultValue={delivered} onBlur={e=>delivery(i,Number(e.target.value))}/><span className={remaining?"font-semibold text-orange-700":"font-semibold text-emerald-700"}>Mancanti: {remaining}</span></div></div>{complete&&<span className="text-xs font-semibold text-emerald-700">Completo</span>}</div>})}</div>:<div className="rounded-xl bg-orange-50 p-4 text-sm text-orange-800">Ordine vocale da trascrivere.</div>}{order.completed_at&&<div className="rounded-xl bg-emerald-50 p-3 text-xs font-semibold text-emerald-800">Completato il {new Date(order.completed_at).toLocaleDateString("it-IT")}. Sarà eliminato automaticamente dopo 14 giorni.</div>}{order.notes&&<div className="rounded-xl bg-amber-50 p-4 text-sm"><b>Note:</b> {order.notes}</div>}<AttachmentList attachments={attachments}/><form action={upload} className="rounded-xl border border-dashed p-4"><div className="mb-3 flex items-center gap-2 font-semibold"><Mic className="size-4 text-orange-500"/>Aggiungi foto o nota vocale</div><div className="flex flex-col gap-2 sm:flex-row"><Input name="title" placeholder="Descrizione allegato (facoltativa)"/><Input name="file" required type="file" accept="image/*,audio/*"/><Button disabled={busy} type="submit"><Upload/>Carica</Button></div></form></div>}
 </DialogContent></Dialog><AlertDialog open={deleting} onOpenChange={setDeleting}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Eliminare l’ordine #{String(order.id).padStart(4,"0")}?</AlertDialogTitle><AlertDialogDescription>Verranno eliminati definitivamente ordine, righe e allegati, anche se non ancora consegnato.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Annulla</AlertDialogCancel><AlertDialogAction variant="destructive" disabled={busy} onClick={remove}>Elimina ordine</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}
